'use client';

/**
 * The Plan tab's own parts around the plan read (lib/plan-pass.ts), in the
 * order the owner fills them: what the commander does, their notes, then
 * the plan itself - generated by Claude or written by the owner, edited in
 * place, read again with the owner's changes kept, and confirmed. Card roles
 * from the read live on the Tags tab (CardRoles). Nothing here reads the deck
 * until the owner presses a button.
 */

import { useCallback, useEffect, useState } from 'react';

import Tip from './Tip';
import * as api from '@/lib/api';
import { CARD_ROLES, COMMANDER_ROLES, SUGGEST_COMMANDER_AT, type CardRole, type CommanderRole, type PlanView, type Route, type Theme } from '@/lib/plan-shared';

const BTN = 'rounded-full border border-[var(--border)] px-3 py-1 text-sm hover:bg-[var(--surface-hover)] disabled:opacity-50';
const AI_BTN = 'rounded-full border border-violet-300/50 px-3 py-1 text-sm hover:bg-violet-300/10 disabled:opacity-50';
const GO = 'rounded-full bg-[var(--accent)] px-4 py-1.5 text-sm font-semibold text-[#221c08] disabled:opacity-50';
const LINK = 'text-sm text-[var(--muted)] underline hover:text-[var(--foreground)] disabled:opacity-50';
const INPUT = 'rounded-lg border border-[var(--border)] bg-[var(--background)] px-2 py-1 text-sm outline-none focus:border-[var(--accent)]';
const COST = 'about $0.20';
const when = (iso: string) => new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

/** The plan view for a deck, kept fresh while a read runs. */
export function usePlanView(listId: string, version: string) {
  const [view, setView] = useState<PlanView | null>(() => api.peek<PlanView>(api.planPath(listId)) ?? null);
  const [error, setError] = useState<string | null>(null);
  const load = useCallback(() => api.planPass(listId).then((v) => { setView(v); setError(null); }).catch((e) => setError(e instanceof Error ? e.message : 'Could not load the plan')), [listId]);
  useEffect(() => { void load(); }, [load, version]);
  const running = view?.job?.status === 'running';
  useEffect(() => {
    if (!running) return;
    const t = setInterval(() => { void load(); }, 3000);
    return () => clearInterval(t);
  }, [running, load]);
  const act = useCallback(async (a: api.PlanPassAction) => {
    try { const v = await api.planPassAct(listId, a); setView(v); setError(null); return v; } catch (e) { setError(e instanceof Error ? e.message : 'Could not do that'); return null; }
  }, [listId]);
  return { view, error, act, reload: load };
}

// --- 1. What the commander does --------------------------------------------------------------

export function CommanderRoles({ view, act, commander, readRoles }: { view: PlanView; act: (a: api.PlanPassAction) => Promise<unknown>; commander: string; readRoles: CommanderRole[] | null }) {
  const picked = new Set(view.commanderRoles);
  const toggle = (id: CommanderRole) => {
    const next = new Set(picked);
    if (next.has(id)) next.delete(id);
    else if (id === 'unsure') { next.clear(); next.add('unsure'); }
    else { next.delete('unsure'); next.add(id); }
    void act({ action: 'commanderRoles', roles: [...next] });
  };
  const changed = readRoles !== null && [...readRoles].sort().join() !== [...picked].sort().join();
  return (
    <section data-tour="plan-commander" className="flex flex-col gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="flex items-center gap-2 font-display text-lg font-semibold"><span className="text-xs text-[var(--faint)]">1</span>What {commander} does for the deck
          <Tip label="About this">Pick any that fit; hover an option for what it means. The plan reads this, and so does every AI step after it.</Tip></h3>
        {changed && view.pass && <span className="text-xs text-violet-200">Changed since the plan was read</span>}
      </div>
      <div role="group" aria-label={`What ${commander} does for the deck`} className="flex flex-wrap gap-1.5">
        {COMMANDER_ROLES.map((r) => (
          <label key={r.id} className={`group relative inline-flex cursor-pointer items-center gap-1.5 rounded-full border px-3 py-1 text-sm focus-within:ring-2 focus-within:ring-[var(--accent)]/50 ${picked.has(r.id) ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border)] hover:bg-[var(--surface-hover)]'}`}>
            <input type="checkbox" className="accent-[var(--accent)]" checked={picked.has(r.id)} onChange={() => toggle(r.id)} />
            {r.label}
            <span role="tooltip" className="pointer-events-none absolute left-0 top-full z-30 mt-1.5 hidden w-72 max-w-[80vw] rounded-lg border border-[var(--border)] bg-[var(--surface)] p-2.5 text-xs leading-snug text-[var(--foreground)] shadow-xl group-hover:block group-focus-within:block">{r.tip}</span>
          </label>
        ))}
      </div>
    </section>
  );
}

// --- 3. Your notes ---------------------------------------------------------------------------

type Note = api.DeckPlanState['notes'][number] & { by?: 'owner' | 'ai' };

export function OwnerNotes({ notes, busy, change }: { notes: Note[]; busy: boolean; change: (c: api.PlanChange) => Promise<void> }) {
  const mine = notes.filter((n) => n.by === 'owner');
  const claude = notes.filter((n) => n.by !== 'owner');
  const [text, setText] = useState('');
  const [editing, setEditing] = useState<{ id: string; text: string } | null>(null);
  return (
    <section data-tour="plan-notes" className="flex flex-col gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="flex items-center gap-2 font-display text-lg font-semibold"><span className="text-xs text-[var(--faint)]">3</span>Your notes
          <Tip label="About your notes">Anything you want the plan and every later AI step to know, in your words: what the deck is for, what to focus on, cards you love. Your answers to the plan&apos;s questions land here too. Claude&apos;s own notes are never sent back as yours.</Tip></h3>
        <span className="text-xs text-[var(--muted)]">Read by the plan and every AI step</span>
      </div>
      {mine.length === 0 && <p className="text-sm text-[var(--muted)]">No notes yet.</p>}
      <ul className="flex flex-col gap-1.5">
        {mine.map((n) => (
          <li key={n.id} className="flex items-start justify-between gap-3 rounded-lg bg-[var(--surface-hover)]/60 px-3 py-2 text-sm">
            {editing?.id === n.id ? (
              <form className="flex min-w-0 flex-1 gap-2" onSubmit={(e) => { e.preventDefault(); void change({ notes: { edit: { id: n.id, text: editing.text } } }); setEditing(null); }}>
                <input autoFocus aria-label="Edit note" value={editing.text} onChange={(e) => setEditing({ id: n.id, text: e.target.value })} className={`${INPUT} min-w-0 flex-1`} />
                <button type="submit" disabled={busy} className={BTN}>Save</button>
                <button type="button" onClick={() => setEditing(null)} className={LINK}>Cancel</button>
              </form>
            ) : (
              <>
                <span className="min-w-0 whitespace-pre-wrap">{n.text}<span className="block text-xs text-[var(--faint)]">{when(n.at)}</span></span>
                <span className="flex shrink-0 gap-3">
                  <button onClick={() => setEditing({ id: n.id, text: n.text })} disabled={busy} className={LINK}>Edit</button>
                  <button onClick={() => change({ notes: { remove: n.id } })} disabled={busy} className={LINK} aria-label="Remove this note">Remove</button>
                </span>
              </>
            )}
          </li>
        ))}
      </ul>
      <form className="flex flex-wrap gap-2" onSubmit={(e) => { e.preventDefault(); if (!text.trim()) return; void change({ notes: { add: [text.trim()] } }); setText(''); }}>
        <label htmlFor="new-note" className="sr-only">Add a note</label>
        <input id="new-note" value={text} onChange={(e) => setText(e.target.value)} maxLength={600} placeholder="e.g. I want it to win through combat more than the loop" className={`${INPUT} min-w-0 flex-[1_1_18rem]`} />
        <button type="submit" disabled={busy || !text.trim()} className={BTN}>Add</button>
      </form>
      {claude.length > 0 && (
        <details className="text-sm">
          <summary className="cursor-pointer text-xs text-[var(--muted)]">Claude&apos;s notes from earlier reads ({claude.length}) · not sent to later AI steps</summary>
          <ul className="mt-2 flex flex-col gap-1">
            {claude.map((n) => <li key={n.id} className="flex items-start justify-between gap-2 text-[var(--muted)]"><span>{n.text}</span><button onClick={() => change({ notes: { remove: n.id } })} disabled={busy} className={LINK} aria-label="Remove this note">Remove</button></li>)}
          </ul>
        </details>
      )}
    </section>
  );
}

// --- 4. The plan --------------------------------------------------------------------------------

type Draft = { plan?: string; winRoutes?: Route[]; keyCards?: string[]; themes?: Theme[] };

function Chip({ text, yours, editing, onRemove, keyCard }: { text: string; yours: boolean; editing: boolean; onRemove: () => void; keyCard?: boolean }) {
  return (
    <span className={`inline-flex items-center gap-1 rounded-lg border px-2 py-0.5 text-sm ${yours && editing ? 'border-[var(--accent)]' : keyCard ? 'border-[var(--accent)]/40' : 'border-[var(--border)]'} bg-[var(--surface-hover)]/50`}>
      {text}
      {yours && editing && <span className="text-[10px] text-[var(--accent)]">yours</span>}
      {editing && <button onClick={onRemove} aria-label={`Remove ${text}`} className="px-0.5 text-[var(--muted)] hover:text-[var(--foreground)]">×</button>}
    </span>
  );
}

function AddBox({ label, cardNames, onAdd }: { label: string; cardNames?: string[]; onAdd: (v: string) => void }) {
  const [v, setV] = useState('');
  const id = `add-${label.replace(/\W+/g, '-').toLowerCase()}`;
  return (
    <form className="inline-flex" onSubmit={(e) => { e.preventDefault(); if (v.trim()) { onAdd(v.trim()); setV(''); } }}>
      <input aria-label={label} placeholder={`+ ${label}`} value={v} onChange={(e) => setV(e.target.value)} list={cardNames ? `${id}-names` : undefined} className={`${INPUT} w-44`} />
      {cardNames && <datalist id={`${id}-names`}>{cardNames.map((n) => <option key={n} value={n} />)}</datalist>}
    </form>
  );
}

/** Keyed by the read's id where it is used: a new read starts with a clean draft. */
export function PlanRead({ view, act, cardNames }: { view: PlanView; act: (a: api.PlanPassAction) => Promise<PlanView | null>; cardNames: string[] }) {
  const p = view.pass;
  const [mode, setMode] = useState<'gen' | 'write'>('gen');
  const [own, setOwn] = useState('');
  const [fill, setFill] = useState(true);
  const [editingConfirmed, setEditingConfirmed] = useState(false);
  const [draft, setDraft] = useState<Draft>({});
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [skipped, setSkipped] = useState<Set<string>>(new Set());
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);

  const run = async (a: api.PlanPassAction) => { setBusy(true); try { return await act(a); } finally { setBusy(false); } };
  const running = view.job?.status === 'running';
  const failed = view.job?.status === 'failed' ? view.job.error : null;

  if (running) {
    return (
      <PlanFrame view={view}>
        <p className="text-sm text-[var(--muted)]">{view.job?.progress ?? 'Reading the deck'}… with what the commander does, your settings and your notes. You can keep using the deck; this fills in by itself.</p>
        {[90, 75, 60].map((w) => <span key={w} className="block h-3 animate-pulse rounded bg-[var(--surface-hover)] motion-reduce:animate-none" style={{ width: `${w}%` }} />)}
      </PlanFrame>
    );
  }

  if (!p) {
    return (
      <PlanFrame view={view}>
        {failed && <p role="alert" className="text-sm text-red-400">The last read failed: {failed}</p>}
        <div role="radiogroup" aria-label="How to make the plan" className="flex flex-wrap gap-1.5">
          {([['gen', 'Have Claude read the deck'], ['write', 'Write it myself']] as const).map(([m, label]) => (
            <button key={m} role="radio" aria-checked={mode === m} onClick={() => setMode(m)} className={`rounded-full border px-3 py-1 text-sm ${mode === m ? 'border-violet-300/70 bg-violet-300/10' : 'border-[var(--border)] text-[var(--muted)]'}`}>{label}</button>
          ))}
        </div>
        {mode === 'gen' ? (
          <div className="flex flex-col gap-3">
            <Reads view={view} />
            <div className="flex flex-wrap items-center gap-3">
              <button onClick={() => run({ action: 'generate' })} disabled={busy} className={GO}>✦ Generate the plan · Opus · {COST}</button>
              <span className="text-xs text-[var(--muted)]">Takes about a minute; you can keep using the deck meanwhile.</span>
            </div>
          </div>
        ) : (
          <div className="flex flex-col gap-2">
            <label htmlFor="own-plan" className="text-sm text-[var(--muted)]">How does the deck win, and what is it built around? A few sentences is plenty.</label>
            <textarea id="own-plan" value={own} onChange={(e) => setOwn(e.target.value)} rows={3} maxLength={2000} className={`${INPUT} w-full`} placeholder="e.g. Cast cheap spells while the commander attacks so they get copied; win with pingers or the red-mana loop." />
            <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={fill} onChange={(e) => setFill(e.target.checked)} /> Have Claude fill in ways to win, key cards, themes and card roles from my plan ({COST})</label>
            <div><button onClick={() => run({ action: 'ownPlan', text: own, fill })} disabled={busy || !own.trim()} className={GO}>Save my plan</button></div>
          </div>
        )}
      </PlanFrame>
    );
  }

  const confirmed = !!view.confirmed;
  const editing = !confirmed || editingConfirmed;
  const shown = { plan: draft.plan ?? p.plan, winRoutes: draft.winRoutes ?? p.winRoutes, keyCards: draft.keyCards ?? p.keyCards, themes: draft.themes ?? p.themes };
  const dirty = Object.keys(draft).length;
  const edits = dirty + view.edits;
  const given = p.questions.filter((q) => answers[q]?.trim() && !skipped.has(q));
  // Confirming counts an unanswered question as skipped; reading again only the ones the owner skipped.
  const input = (confirming: boolean) => ({
    answers: given.map((q) => ({ question: q, answer: answers[q].trim() })),
    skipped: p.questions.filter((q) => skipped.has(q) || (confirming && !answers[q]?.trim())),
    note: note.trim(),
  });
  const saveDraft = async () => { if (dirty) await act({ action: 'edits', edits: draft }); };
  const reread = async () => { setBusy(true); try { await saveDraft(); setNote(''); await act({ action: 'generate', ...input(false) }); } finally { setBusy(false); } };
  const confirm = async () => { setBusy(true); try { await saveDraft(); setNote(''); await act({ action: 'confirm', ...input(true) }); setDraft({}); setEditingConfirmed(false); } finally { setBusy(false); } };
  const set = (d: Draft) => setDraft((x) => ({ ...x, ...d }));
  const youKey = new Set(p.yours.keyCards);
  const youTheme = new Set(p.yours.themes);
  const youRoute = new Set(p.yours.routes);
  const youRouteCard = new Set(p.yours.routeCards);

  return (
    <PlanFrame view={view}>
      {view.stale && !view.stale.usingAnyway && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-300/60 bg-amber-300/[0.07] px-3 py-2.5 text-sm">
          <span><b>Out of date.</b> <span className="text-[var(--muted)]">{[view.stale.changed >= 1 ? `${view.stale.changed} cards changed since it was read (${when(p.at)})` : '', view.stale.commander ? 'the commander changed' : '', view.stale.keyCardsGone.length ? `key card${view.stale.keyCardsGone.length === 1 ? '' : 's'} gone: ${view.stale.keyCardsGone.join(', ')}` : ''].filter(Boolean).join('; ')}. AI steps won&apos;t use it until it&apos;s read again.</span></span>
          <span className="flex flex-wrap items-center gap-3"><button onClick={reread} disabled={busy} className={AI_BTN}>✦ Read again · {COST}</button><button onClick={() => run({ action: 'useStale' })} disabled={busy} className={LINK}>Use it anyway</button></span>
        </div>
      )}
      {failed && <p role="alert" className="text-sm text-red-400">The last read failed: {failed}. The plan below is from before.</p>}

      <div className="flex flex-wrap items-center gap-2">
        <span className="text-[11px] font-semibold uppercase tracking-wide text-violet-200">{p.ownPlan ? 'Your plan' : '✦ Claude’s read'}</span>
        {!p.ownPlan && <span className={`rounded-md px-1.5 text-[11px] font-semibold leading-5 ${p.state === 'focused' ? 'bg-emerald-500/15 text-emerald-300' : 'bg-amber-300/15 text-amber-200'}`}>{p.state === 'focused' ? 'Focused' : p.state === 'unfocused' ? 'Unfocused' : 'No clear plan'}</span>}
        {confirmed && <span className="rounded-md bg-[var(--accent)]/15 px-1.5 text-[11px] font-semibold leading-5 text-[var(--accent)]">✓ Confirmed by you · {when(view.confirmed!.at)}</span>}
        {confirmed && !editingConfirmed && (
          <button onClick={() => setEditingConfirmed(true)} aria-label="Edit the plan" title="Edit the plan" className="ml-auto inline-flex h-8 w-8 items-center justify-center rounded-lg border border-[var(--border)] hover:bg-[var(--surface-hover)]">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg>
          </button>
        )}
      </div>
      {confirmed && editingConfirmed && <p className="text-xs text-violet-200">Editing the plan: change anything below, then use the panel at the bottom.</p>}

      {editing
        ? <textarea aria-label="The plan" value={shown.plan} onChange={(e) => set({ plan: e.target.value })} rows={4} className={`${INPUT} w-full max-w-3xl leading-relaxed`} />
        : <p className="max-w-3xl leading-relaxed">{shown.plan}</p>}

      <div className="flex flex-col gap-2.5">
        <h4 className="flex items-center gap-1.5 text-sm font-semibold">Ways to win<Tip label="About ways to win">How the deck ends games. Edit any: remove a card with ×, add one in the box, add or remove a whole way to win. Anything you change is yours, kept exactly the next time the plan is read.</Tip></h4>
        {shown.winRoutes.length === 0 && <p className="text-sm text-[var(--muted)]">None found.</p>}
        {shown.winRoutes.map((r, i) => (
          <div key={`${r.name}-${i}`} className="grid gap-x-3 gap-y-1.5 border-t border-dashed border-[var(--border)] pt-2.5 first-of-type:border-t-0 first-of-type:pt-0 sm:grid-cols-[minmax(8rem,12rem)_1fr]">
            <span className="text-sm">{r.name}{editing && youRoute.has(r.name) && <span className="ml-1 text-[10px] text-[var(--accent)]">yours</span>}
              {editing && <button onClick={() => set({ winRoutes: shown.winRoutes.filter((_, j) => j !== i) })} className="block text-xs text-[var(--muted)] underline">Remove this way to win</button>}</span>
            <span className="flex flex-col gap-1">
              <span className="flex flex-wrap items-center gap-1.5">
                {r.cards.map((c, j) => <Chip key={c} text={c} yours={youRouteCard.has(c)} editing={editing} onRemove={() => set({ winRoutes: shown.winRoutes.map((x, k) => (k === i ? { ...x, cards: x.cards.filter((_, m) => m !== j) } : x)) })} />)}
                {editing && <AddBox label={`card for ${r.name}`} cardNames={cardNames} onAdd={(v) => set({ winRoutes: shown.winRoutes.map((x, k) => (k === i ? { ...x, cards: [...x.cards, v] } : x)) })} />}
              </span>
              {p.oneAway.filter((c) => c.cards.some((n) => r.cards.includes(n))).map((c) => (
                <span key={c.missing} className="text-xs text-amber-200">▲ One card away: add <b>{c.missing}</b> to complete {c.cards.filter((n) => n !== c.missing).join(' + ')} (from the combo list, not the AI).</span>
              ))}
            </span>
          </div>
        ))}
        {editing && <AddBox label="way to win" onAdd={(v) => set({ winRoutes: [...shown.winRoutes, { name: v, cards: [] }] })} />}
      </div>

      <div className="flex flex-col gap-2">
        <h4 className="flex items-center gap-1.5 text-sm font-semibold">Key cards<Tip label="About key cards">Cards the deck can&apos;t work without. Add or remove any; your changes are kept on the next read. To keep a card from ever being offered as a cut, mark it ★ never cut.</Tip></h4>
        <div className="flex flex-wrap items-center gap-1.5">
          {shown.keyCards.map((c, i) => <Chip key={c} keyCard text={c} yours={youKey.has(c)} editing={editing} onRemove={() => set({ keyCards: shown.keyCards.filter((_, j) => j !== i) })} />)}
          {editing && <AddBox label="key card" cardNames={cardNames} onAdd={(v) => set({ keyCards: [...shown.keyCards, v] })} />}
        </div>
        <h4 className="mt-1 text-sm font-semibold">Themes</h4>
        <div className="flex flex-wrap items-center gap-1.5">
          {shown.themes.map((t, i) => <Chip key={t.name} text={`${t.name}${t.cards.length ? ` · ${t.cards.length}` : ''}`} yours={youTheme.has(t.name)} editing={editing} onRemove={() => set({ themes: shown.themes.filter((_, j) => j !== i) })} />)}
          {editing && <AddBox label="theme" onAdd={(v) => set({ themes: [...shown.themes, { name: v, cards: [] }] })} />}
        </div>
      </div>

      {p.summary && <p className="max-w-3xl text-sm text-[var(--muted)]">{p.summary}</p>}

      {p.commander && !editingConfirmed && (
        <div className="flex flex-col gap-2 rounded-xl border border-violet-300/30 bg-[var(--surface-hover)]/50 p-3">
          <span className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-violet-200">✦ What the commander does for the deck<Tip label="About this suggestion">You picked Unsure, so the plan suggests an answer once you&apos;ve confirmed it. It came with the read, at no extra cost.</Tip></span>
          <p className="text-sm"><b>{p.commander.roles.map((r) => COMMANDER_ROLES.find((x) => x.id === r)?.label).join(' and ')}</b>. <span className="text-[var(--muted)]">{p.commander.why}</span></p>
          <span className="flex flex-wrap items-center gap-3"><button onClick={() => run({ action: 'acceptCommander' })} disabled={busy} className={GO}>Use these</button><span className="text-xs text-[var(--muted)]">Or pick yourself in step 1.</span></span>
        </div>
      )}
      {view.commanderRoles.includes('unsure') && !p.commander && !confirmed && view.nonland >= SUGGEST_COMMANDER_AT && <p className="text-xs text-[var(--faint)]">What the commander does: suggested once you confirm the plan.</p>}
      {view.commanderRoles.includes('unsure') && view.nonland < SUGGEST_COMMANDER_AT && <p className="text-xs text-[var(--faint)]">What the commander does: suggested once the deck has {SUGGEST_COMMANDER_AT} or more non-land cards ({view.nonland} now).</p>}

      {p.questions.length > 0 && editing && (
        <div className="flex flex-col gap-3 rounded-xl border border-violet-300/30 bg-[var(--surface-hover)]/50 p-3">
          <span className="flex items-center justify-between gap-2"><span className="text-[11px] font-semibold uppercase tracking-wide text-violet-200">✦ {p.questions.length} question{p.questions.length === 1 ? '' : 's'} about this deck</span>
            <button onClick={() => setSkipped(new Set(p.questions))} className={LINK}>Skip all</button></span>
          {p.questions.map((q, i) => (
            <div key={q} className={`flex flex-col gap-1.5 ${skipped.has(q) ? 'opacity-50' : ''}`}>
              <label htmlFor={`q-${i}`} className="text-sm">{q}</label>
              <span className="flex gap-2"><input id={`q-${i}`} value={answers[q] ?? ''} disabled={skipped.has(q)} onChange={(e) => setAnswers((a) => ({ ...a, [q]: e.target.value }))} placeholder="A line is plenty" className={`${INPUT} min-w-0 flex-1`} />
                <button onClick={() => setSkipped((s) => { const n = new Set(s); if (n.has(q)) n.delete(q); else n.add(q); return n; })} className={LINK}>{skipped.has(q) ? 'Answer' : 'Skip'}</button></span>
            </div>
          ))}
          <p className="text-xs text-[var(--faint)]">Answers go to your notes when you read again or confirm below.</p>
        </div>
      )}

      {editing && (
        <div className="flex flex-col gap-2 rounded-xl border border-violet-300/40 bg-violet-300/[0.04] p-3">
          <span className="flex items-center justify-between gap-2"><b className="text-sm">Adjust the plan</b>
            <Tip label="About adjusting the plan">One place to change the plan: edit anything above, answer the questions, and tell Claude anything else. Reading again keeps your edits exactly and fills in the rest, asking again only if something is still open. It reads what the commander does, your settings, your notes and the whole deck. Confirming says this is your deck&apos;s plan; Tune, Chat and Check work before that too.</Tip></span>
          <span className="flex flex-wrap gap-1.5 text-xs">
            {[[edits, `${edits} edit${edits === 1 ? '' : 's'} above`], [given.length, `${given.length} answer${given.length === 1 ? '' : 's'}`], [note.trim() ? 1 : 0, note.trim() ? 'a note for Claude' : 'no note']].map(([n, label]) => (
              <span key={String(label)} className={`rounded-full border px-2 py-0.5 ${n ? 'border-[var(--accent)]' : 'border-[var(--border)] text-[var(--muted)]'}`}>{label}</span>
            ))}
            <span className="rounded-full border border-[var(--border)] px-2 py-0.5 text-[var(--muted)]">+ commander, settings, your notes</span>
          </span>
          <label htmlFor="tell-claude" className="text-xs text-[var(--muted)]">Anything else to tell Claude? What&apos;s wrong, what to focus on. Saved to your notes.</label>
          <textarea id="tell-claude" value={note} onChange={(e) => setNote(e.target.value)} rows={2} maxLength={2000} className={`${INPUT} w-full`} placeholder="e.g. The main loop is a different one, and I want to lean on combat more." />
          <span className="flex flex-wrap items-center gap-3">
            <button onClick={reread} disabled={busy} className={AI_BTN}>✦ Read again with my changes · {COST}</button>
            {!confirmed && <button onClick={confirm} disabled={busy} className={GO}>Confirm the plan</button>}
            {confirmed && <><button onClick={confirm} disabled={busy} className={GO}>Save and confirm</button><button onClick={() => { setDraft({}); setNote(''); setEditingConfirmed(false); }} disabled={busy} className={LINK}>Cancel</button></>}
            {view.edits > 0 && <button onClick={() => { setDraft({}); void run({ action: 'undoEdits' }); }} disabled={busy} className={LINK}>Undo my edits</button>}
          </span>
        </div>
      )}
      {!p.ownPlan && <p className="text-xs text-[var(--faint)]">{p.model} · read {when(p.at)}</p>}
    </PlanFrame>
  );
}

function PlanFrame({ view, children }: { view: PlanView; children: React.ReactNode }) {
  return (
    <section data-tour="plan-read" className={`flex flex-col gap-4 rounded-2xl border bg-[var(--surface)] p-4 ${view.stale && !view.stale.usingAnyway ? 'border-amber-300/60' : 'border-violet-300/40'}`}>
      <h3 className="flex items-center gap-2 font-display text-lg font-semibold"><span className="text-xs text-[var(--faint)]">4</span>The plan
        <Tip label="About the plan">How the deck wins, its key cards and themes, and anything worth asking you. Generate it, or write it yourself. Tune, Chat and Check can be used either way; they read the plan once there is one.</Tip></h3>
      {children}
    </section>
  );
}

function Reads({ view }: { view: PlanView }) {
  return (
    <div className="rounded-xl bg-[var(--surface-hover)]/50 p-3 text-sm">
      <b>What it reads</b>
      <ul className="mt-1 list-disc pl-5 text-[var(--muted)]">
        <li>What the commander does for the deck <span className="text-[var(--faint)]">({view.commanderRoles.map((r) => COMMANDER_ROLES.find((x) => x.id === r)?.label).join(', ')})</span></li>
        <li>Your settings</li>
        <li>Your notes <span className="text-[var(--faint)]">({view.reads.notes})</span></li>
        <li>The commander and every card&apos;s full rules text</li>
        <li>The numbers the app counted: lands, ramp, draw, curve, combos</li>
      </ul>
      <p className="mt-1.5 text-xs text-[var(--faint)]">Fill in 1–3 first if you can. Nothing is read until you press the button.</p>
    </div>
  );
}

// --- Tags tab: every card's role ------------------------------------------------------------

export function CardRoles({ listId, version }: { listId: string; version: string }) {
  const { view, act, error } = usePlanView(listId, version);
  if (error) return <p className="text-sm text-red-400">{error}</p>;
  if (!view) return <p className="text-sm text-[var(--muted)]">Loading…</p>;
  const cards = view.pass?.cards ?? {};
  const names = Object.keys(cards);
  return (
    <section className="flex flex-col gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 className="flex items-center gap-2 font-display text-lg font-semibold">Card roles<Tip label="About card roles">One role per card, from the plan read. Change any if the read got it wrong: your change is kept on every later read and read by the AI steps.</Tip></h2>
        {view.pass && !view.pass.ownPlan && <span className="text-xs text-[var(--muted)]">from the plan · {when(view.pass.at)}</span>}
      </div>
      {!names.length ? <p className="text-sm text-[var(--muted)]">No roles yet. They come with the plan read on the Plan tab.</p> : (
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {CARD_ROLES.map((r) => {
            const inRole = names.filter((n) => cards[n].role === r.id).sort();
            if (!inRole.length) return null;
            return (
              <div key={r.id} className="min-w-0 rounded-xl bg-[var(--surface-hover)]/50 p-3">
                <span className="flex items-center gap-1.5 text-sm font-semibold">{r.label} <span className="text-xs font-normal text-[var(--muted)]">· {inRole.length}</span><Tip label={`About ${r.label}`}>{r.tip}</Tip></span>
                <ul className="mt-2 flex flex-col gap-1.5">
                  {inRole.map((n) => (
                    <li key={n} className="flex items-start justify-between gap-2 text-sm">
                      <span className="min-w-0">{n}{cards[n].yours && <span className="ml-1 text-[10px] text-[var(--accent)]">yours</span>}<span className="block text-xs text-[var(--faint)]">{cards[n].note}</span></span>
                      <select aria-label={`Role of ${n}`} value={cards[n].role} onChange={(e) => void act({ action: 'edits', edits: { roles: { [n]: e.target.value as CardRole } } })} className={`${INPUT} shrink-0 py-0.5 text-xs`}>
                        {CARD_ROLES.map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
                      </select>
                    </li>
                  ))}
                </ul>
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}
